// --- Basic Traversal (Forward/Bidirectional) ---
std::vector<int> v = {1, 2, 3};
for (auto it = v.begin(); it != v.end(); ++it) {
    std::cout << *it << " ";
}
// Range-based for uses iterators internally:
for (int x : v) { /* ... */ }

// --- Algorithm Application (Generic) ---
template <typename Iterator>
void print_range(Iterator first, Iterator last) {
    while (first != last) {
        std::cout << *first++ << " ";
    }
}
std::list<int> l = {4, 5};
print_range(l.begin(), l.end());

// --- Random Access Iterator (RAI) Operations ---
std::vector<int> w = {10, 20, 30, 40};
auto it_start = w.begin();
auto it_mid = it_start + 2; // O(1) jump
int dist = std::distance(it_start, it_mid); // O(1) for RAI
if (it_start < it_mid) { /* Comparison possible */ }

// --- Insert Iterator (Output Iterator) ---
std::vector<int> source = {1, 2};
std::list<int> dest;
std::copy(source.begin(), source.end(), std::back_inserter(dest));
// Other specific output iterators:
// std::front_inserter (for list/deque)
// std::inserter (pos, value)

// --- Stream Iterators (Input/Output) ---
std::vector<int> data;
// Input stream:
std::copy(std::istream_iterator<int>(std::cin),
          std::istream_iterator<int>(),
          std::back_inserter(data));
// Output stream:
std::copy(data.begin(), data.end(),
          std::ostream_iterator<int>(std::cout, ", "));

// --- Custom/Adaptor Iterators (Example: Reverse) ---
std::vector<int> seq = {10, 20, 30};
// Traverse backwards:
for (auto it = seq.rbegin(); it != seq.rend(); ++it) {
    std::cout << *it << " ";
}
// Note: seq.rbegin() is essentially a wrapper around seq.end()
